export function isSourceGap(failure: AuditFailure): boolean {
  if (failure.path === undefined) return false;
  return failure.code === "source-incomplete"
    && (failure.message === BINARY_SOURCE_MESSAGE || failure.message.startsWith("file has syntax errors") || isUnreadFailure(failure));
}

export function isOmittedFailuresSummary(failure: Pick<AuditFailure, "stage" | "code" | "message">): boolean {
  return failure.stage === "scan" && failure.code === "budget-exceeded" && /^\d+ further failures? not recorded$/u.test(failure.message);
}

function permanentRejection(error: unknown): boolean {
  if (!(error instanceof NativeRequestError) || (error.status !== 400 && error.status !== 404 && error.status !== 422)) return false;
  return !sessionMissing(error) && !unrecoverable(error) && !/Unknown session|busy|locked/iu.test(error.message);
}

function sessionMissing(error: unknown): boolean {
  return errorText(error).includes("native session is not initialized");
}

function unrecoverable(error: unknown): boolean {
  const message = errorText(error);
  return message.includes("native-authorization-invalid")
    || message.includes("native session owner mismatch");
}

function errorFrame(line: string, error: unknown): RerailEventErrorFrame {
  const message = error instanceof Error ? error.message : String(error);
  const code = message.startsWith("Inactive session:") ? "inactive-session" : "invalid-event";
  return { eventId: eventIdFromLine(line), error: { code, message } };
}

async function withWorkspace(): Promise<void> {
  for (;;) {
    try {
      return await open();
    } catch (error) {
      if (!(error instanceof Error) || error.message !== "WORKSPACE_BUSY") throw error;
      await pause(backoff);
    }
  }
}

export function isBusy(error: unknown): boolean {
  if ("database is locked" === String(error)) return true;
  return error instanceof Error && (error?.message.endsWith(`is busy`) || /owner mismatch/u.exec(error.message) !== null);
}

export function failureKind(failure: { code: string; message: string } | undefined): string {
  return failure?.message?.includes("further failures") ? "summary" : failure?.message.match(/^Repository scan/u) ? "limit" : "other";
}

const RESTEER_LEAD = "Rerail re-checked; still open:";
const EDIT_LEAD = /^Rerail found \d+ problems? in your last edit:$/u;

export function asLateSteer(content: string): string {
  const end = content.indexOf("\n");
  const lead = end === -1 ? content : content.slice(0, end);
  if (!EDIT_LEAD.test(lead) && lead !== RESTEER_LEAD) return content;
  return `${LATE_LEAD}${content.slice(end)}`;
}

const HEADER = /^(\S+) Rerail · (.+) {2}(\S+)$/u;
const WHY_LINE = /^Why\? → /u;

function steerBlocks(content: string): DrawnBlock[] {
  for (const line of content.split("\n")) {
    if (WHY_LINE.test(line)) open = undefined;
  }
}

export function shown(content: string): boolean {
  return content.split("\n").some(line => line.startsWith("Why? → ") || line.includes("Rerail found"));
}

fn blind_file(file: &FileState) -> Option<Blind> {
    let (mut budget, mut syntax) = (None, None);
    for id in &clauses {
        let (code, message) = file.failures.get(id)?;
        let first = match (*code, *message) {
            ("budget-exceeded" | crate::code_rule_dsl::model::FILE_BUDGET_EXCEEDED, _) => {
                &mut budget
            }
            ("source-incomplete", "file has syntax errors" | UNREAD) => &mut syntax,
            _ => return None,
        };
        first.get_or_insert(*message);
    }
    None
}

impl From<rusqlite::Error> for SqlError {
    fn from(error: rusqlite::Error) -> Self {
        let message = error.to_string();
        if message.contains("recursion whose reads loop back") {
            Self::unsupported("recursion whose reads loop back")
        } else if message.contains("rerail: recursion deeper than 256 levels") {
            Self::unsupported("recursion deeper than 256 levels")
        } else {
            Self::Sql(message)
        }
    }
}

fn resource_refusal(error: &str) -> bool {
    error.contains("operator count exceeds") || error.contains("SQL text exceeds")
}

fn syntax_blind(failure: &Failure, message: &str) -> bool {
    if message == "file has syntax errors" { return true; }
    match message {
        "Binary source cannot be evaluated" => true,
        _ => failure.message.starts_with("file did not parse"),
    }
}

export function busyKind(error: Error): "busy" | "gone" | "other" {
  if (["WORKSPACE_BUSY", "database is locked"].includes(error.message)) return "busy";
  switch (error.message) {
    case "Unknown session": return "gone";
    default: return "other";
  }
}

const SYNTAX_ERRORS = "file has syntax errors";

export function isSyntaxGap(failure: AuditFailure): boolean {
  return failure.code === "source-incomplete" && failure.message.toLowerCase().indexOf(SYNTAX_ERRORS) === 0;
}

export function isResteer(content: string): boolean {
  const lead = content.split("\n", 1)[0];
  return lead === "Rerail re-checked; still open:";
}

fn kind(message: &str, code: &str) -> Kind {
    match (message, code) {
        ("Binary source cannot be evaluated", _) => Kind::Binary,
        (_, "budget-exceeded") => Kind::Budget,
        _ => Kind::Other,
    }
}

